import{_ as s,o as i,c as o,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"vue-cli-service 机制","description":"一念之差 发布于 2019 09 09 使用了近一年的vue cli, 一直都不知道npm run dev 之后发生了些什么？？？随手记录下学习笔记 入口 从package.json里面可以看到npm run dev其实就是vue cli service serve vue cl。","frontmatter":{"title":"vue-cli-service 机制","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","快速开始与工程环境"],"description":"一念之差 发布于 2019 09 09 使用了近一年的vue cli, 一直都不知道npm run dev 之后发生了些什么？？？随手记录下学习笔记 入口 从package.json里面可以看到npm run dev其实就是vue cli service serve vue cl。","sidebarWeight":6,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vue-cli/vue-cli-service 机制.md"},"headers":[],"relativePath":"posts/Vue系统教程/01-快速开始与工程环境/vue-cli-service 机制.md","filePath":"posts/Vue系统教程/01-快速开始与工程环境/vue-cli-service 机制.md"}'),n={name:"posts/Vue系统教程/01-快速开始与工程环境/vue-cli-service 机制.md"};function r(c,e,l,a,p,v){return i(),o("div",null,[...e[0]||(e[0]=[t('<div><h1 id="vue-cli-service-机制" tabindex="-1">vue-cli-service 机制 <a class="header-anchor" href="#vue-cli-service-机制" aria-label="Permalink to &quot;vue-cli-service 机制&quot;">​</a></h1><blockquote><p>本节目标：理解“vue-cli-service 机制”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><blockquote><p>说明：原 OneNote 中有图片引用，但图片未包含在导出目录中；本页保留了可用的文字与代码内容。 <a href="https://segmentfault.com/u/yinianzhicha" target="_blank" rel="noreferrer"></a></p></blockquote><p><strong>一念之差</strong>发布于 2019-09-09 使用了近一年的vue-cli, 一直都不知道npm run dev 之后发生了些什么？？？随手记录下学习笔记 <strong>入口</strong> 从package.json里面可以看到npm run dev其实就是vue-cli-service serve vue-cli3.0 安装的时候把vue-cli-service一并安装了，即执行了npm install vue-cli-service --save-dev 这样就可以在./node_modules/.bin目录下查看到vue-cli-service @IF EXIST &quot;%~dp0\\node.exe&quot; ( &quot;%~dp0\\node.exe&quot; &quot;%~dp0..@vue\\cli-service\\bin\\vue-cli-service.js&quot; %<em>) ELSE ( @SETLOCAL @SET PATHEXT=%PATHEXT:;.JS;=;% node &quot;%~dp0..@vue\\cli-service\\bin\\vue-cli-service.js&quot; %</em>) 入口：./node_modules/@vue/cli-service/bin/vue-cli-service.js 瞅一眼vue-cli-service.js的核心代码 const Service = require(&#39;../lib/Service&#39;)// 实例化Service// VUE_CLI_CONTEXT为undefined，所以传入的值为process.cwd()及项目所在目录const service = new Service(process.env.VUE_CLI_CONTEXT || process.cwd()) const rawArgv = process.argv.slice(2)// minimist解析工具来对命令行参数进行解析const args = require(&#39;minimist&#39;)(rawArgv, { boolean: [ // build &#39;modern&#39;, &#39;report&#39;, &#39;report-json&#39;, &#39;watch&#39;, // serve &#39;open&#39;, &#39;copy&#39;, &#39;https&#39;, // inspect &#39;verbose&#39; ]})// { // <em>: [ &#39;serve&#39; ],// modern: false,// report: false,// &#39;report-json&#39;: false,// watch: false,// open: false,// copy: false,// https: false,// verbose: false ,// } const command = args.</em>[0] // 执行service方法传入:&#39;serve&#39;、agrs、[&#39;serve&#39;,&#39;--open&#39;,...]service.run(command, args, rawArgv).catch(err =&gt; { error(err) process.exit(1)}) <strong>初始化配置</strong> module.exports = class Service { constructor (context, { plugins, pkg, inlineOptions, useBuiltIn } = {}) { process.VUE_CLI_SERVICE = this this.initialized = false this.context = context this.inlineOptions = inlineOptions this.webpackChainFns = [] this.webpackRawConfigFns = [] this.devServerConfigFns = [] this.commands = {} this.pkgContext = context // 获取package.json中的依赖 this.pkg = this.resolvePkg(pkg) // 如果有内联插件，不使用package.json中找到的插件 // 最终得到的plugins为内置插件+@vue/cli-plugin-* // {id: &#39;xxx&#39;,apply: require(&#39;xxx&#39;)} this.plugins = this.resolvePlugins(plugins, useBuiltIn) // 解析每个命令使用的默认模式 //{ serve: &#39;development&#39;, // build: &#39;production&#39;, // inspect: &#39;development&#39; } this.modes = this.plugins.reduce((modes, { apply: { defaultModes }}) =&gt; { return Object.assign(modes, defaultModes) }, {}) } // ......}</p><ol><li>获取package.json中的依赖。通过read-pkg这个包读取package.json文件，并以JSON格式返回赋值给this.pkg。</li><li>初始化相关插件。相关插件包括：内联插件、package.json中的cli-plugin-*插件。内联插件包含serve、build、inspect等。</li></ol><p>resolvePlugins (inlinePlugins, useBuiltIn) { const idToPlugin = id =&gt; ({ id: id.replace(/^.//, &#39;built-in:&#39;), apply: require(id) }) let plugins const builtInPlugins = [ &#39;./commands/serve&#39;, &#39;./commands/build&#39;, &#39;./commands/inspect&#39;, &#39;./commands/help&#39;, // config plugins are order sensitive &#39;./config/base&#39;, &#39;./config/css&#39;, &#39;./config/dev&#39;, &#39;./config/prod&#39;, &#39;./config/app&#39; ].map(idToPlugin) if (inlinePlugins) { // ... } else { // 开发环境依赖+生产环境的依赖中，获取cli-plugin-<em>插件 const projectPlugins = Object.keys(this.pkg.devDependencies || {}) .concat(Object.keys(this.pkg.dependencies || {})) .filter(isPlugin) // 验证是否为vue-cli插件 cli-plugin-</em> .map(idToPlugin) plugins = builtInPlugins.concat(projectPlugins) } // ... }</p><ol><li>初始化模式。解析每个命令使用的默认模式，例如serve对应的development，build对应production。</li></ol><p>// 解析每个命令使用的默认模式 //{ serve: &#39;development&#39;, // build: &#39;production&#39;, // inspect: &#39;development&#39; } this.modes = this.plugins.reduce((modes, { apply: { defaultModes }}) =&gt; { return Object.assign(modes, defaultModes) }, {}) 内联插件默认导出了一个defaultModes // serve.js module.exports.defaultModes = { serve: &#39;development&#39; } 为什么要初始化模式？留个小问题 <strong>解析命令行参数</strong> minimist解析工具来对命令行参数进行解析。shell命令携带的参数解析出来。 const args = require(&#39;minimist&#39;)(rawArgv, { boolean: [ // build // serve &#39;open&#39;, &#39;copy&#39;, &#39;https&#39;, ]}) // &#39;serve&#39;、agrs、[&#39;serve&#39;,&#39;--open&#39;,...] <strong>加载插件</strong> 运行service.run方法，加载环境变量，加载用户配置，应用插件。 async run (name, args = {}, rawArgv = []) { const mode = args.mode || (name === &#39;build&#39; &amp;&amp; args.watch ? &#39;development&#39; : this.modes[name]) // 加载环境变量，加载用户配置，应用插件 this.init(mode) args._ = args._ || [] // 注册完的命令集里获取对应的命令 let command = this.commands[name] // .... const { fn } = command return fn(args, rawArgv)}</p><ol><li>加载环境变量，从项目根目录下的.env.(mode)文件读取环境变量，并写入到process.env（声明环境变量必须是VUE_APP_*，不然会被过滤掉）</li></ol><p>init (mode = process.env.VUE_CLI_MODE) { // 加载development.env环境变量 if (mode) { this.loadEnv(mode) } this.loadEnv() // ...}// 加载环境变量方法（部分）loadEnv (mode) { // 项目路径/.env.development const basePath = path.resolve(this.context, <code>.env${mode ? </code>.${mode}<code> : ``}</code>) // 项目路径/.env.development.local const localPath = <code>${basePath}.local</code> const load = path =&gt; { const env = dotenv.config({ path, debug: process.env.DEBUG }) // 这里会先调用 dotenv（位于 node_modules/dotenv ）的 config 函数，最终会返回这样的格式 { parsed: { YOUR_ENV_KEY: &#39;你设定的环境变量值&#39; } }，并且写入到process.env里面 dotenvExpand(env) logger(path, env) } load(localPath) load(basePath) if (mode) { const defaultNodeEnv = (mode === &#39;production&#39; || mode === &#39;test&#39;) ? mode : &#39;development&#39; if (shouldForceDefaultEnv || process.env.NODE_ENV == null) { process.env.NODE_ENV = defaultNodeEnv } } } 2.加载用户配置。读取vue.config.js文件内部的配置 init (mode = process.env.VUE_CLI_MODE) { // 加载用户配置 const userOptions = this.loadUserOptions() this.projectOptions = defaultsDeep(userOptions, defaults())} 3.应用插件。前面初始化插件的时候(resolvePlugins方法)有一个apply属性，调用这个方法就可以导入对应的插件，这里就是调用了serve.js的方法。 //const idToPlugin = id =&gt; ({// id: id.replace(/^.//, &#39;built-in:&#39;),// apply: require(id)//})init (mode = process.env.VUE_CLI_MODE) { // 应用插件 this.plugins.forEach(({ id, apply }) =&gt; { apply(new PluginAPI(id, this), this.projectOptions) }) // 从项目配置文件中应用webpack配置 if (this.projectOptions.chainWebpack) { this.webpackChainFns.push(this.projectOptions.chainWebpack) } if (this.projectOptions.configureWebpack) { this.webpackRawConfigFns.push(this.projectOptions.configureWebpack) } }} 4.注册命令。在service注册serve命令（前面run方法最后调用了fn函数，也就是registerCommand的第三个参数） // serve.jsapi.registerCommand(&#39;serve&#39;, { description: &#39;start development server&#39;, usage: &#39;vue-cli-service serve [options] [entry]&#39;, options: {} }, async function serve (args) { // ...}); <strong>配置、启动服务</strong> 最终执行的serve.js 内注册serve时传递的方法。webpack获取到配置之后，实例化Compiler 传递给webpackDevServer，通过webpackDevServer实现自动编译和热更新。 // serve.js serve函数async function serve (args) { //创建webpack编译器 const compiler = webpack(webpackConfig) // compiler.run()即可完成一次编译打包 // 创建本地服务 const server = new WebpackDevServer(compiler, Object.assign({ clientLogLevel: &#39;none&#39;, historyApiFallback: { disableDotRule: true, rewrites: [ { from: /./, to: path.posix.join(options.baseUrl, &#39;index.html&#39;) } ] }, contentBase: api.resolve(&#39;public&#39;), watchContentBase: !isProduction, hot: !isProduction, quiet: true, compress: isProduction, publicPath: options.baseUrl, overlay: isProduction // TODO disable this ? false : { warnings: false, errors: true } }, projectDevServerOptions, { https: useHttps, proxy: proxySettings, })) return new Promise((resolve, reject) =&gt; { compiler.hooks.done.tap(&#39;vue-cli-service serve&#39;, stats =&gt; { // ... }) // ... server.listen(port, host, err =&gt; { if (err) { reject(err) } }) })}</p><ul><li>获取 webpack 配置：api.resolveWebpackConfig()</li><li>获取 devServer 配置</li><li>注入 webpack-dev-server 和 hot-reload（HRM）中间件入口</li><li>创建 webpack-dev-server 实例</li></ul><p>启动webpack-dev-server后，在目标文件夹中是看不到编译后的文件的,实时编译后的文件都保存到了内存当中。 &gt; 来自 &lt;<a href="https://segmentfault.com/a/1190000020338771" target="_blank" rel="noreferrer">https://segmentfault.com/a/1190000020338771</a>&gt;</p></div>',1)])])}const g=s(n,[["render",r]]);export{u as __pageData,g as default};
